<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { baseTareajeLabels, cambiarEstadoRegimen, descuentoLabels, guardarRegimen, listarRegimenes } from '../services/regimenes'
import type { Regimen, RegimenPayload } from '../interfaces/regimenes.interface'
const rows=ref<Regimen[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const defaults:RegimenPayload={codigo:'',descripcion:'',horas_ordinarias_mes:240,horas_dia:8,base_tareaje_default:'MES_30_DIAS',tolerancia_tardanza_minutos:0,modo_descuento_tardanza:'NO_ACUMULABLE',afecto_gratificacion:true,afecto_cts:true,afecto_vacaciones:true}
const form=reactive<RegimenPayload>({...defaults})
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarRegimenes(criterio.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item?:Regimen){editing.value=item?.id??null;Object.assign(form,item?{codigo:item.codigo,descripcion:item.descripcion,horas_ordinarias_mes:Number(item.horas_ordinarias_mes),horas_dia:Number(item.horas_dia),base_tareaje_default:item.base_tareaje_default,tolerancia_tardanza_minutos:item.tolerancia_tardanza_minutos,modo_descuento_tardanza:item.modo_descuento_tardanza,afecto_gratificacion:item.afecto_gratificacion,afecto_cts:item.afecto_cts,afecto_vacaciones:item.afecto_vacaciones}:{...defaults});error.value='';modal.value=true}
function validate(){if(form.codigo.trim().length<2)return 'El código debe tener al menos 2 caracteres.';if(form.codigo.trim().length>10)return 'El código admite como máximo 10 caracteres.';if(form.descripcion.trim().length<3)return 'La descripción debe tener al menos 3 caracteres.';if(form.horas_ordinarias_mes<.01)return 'Las horas ordinarias mensuales deben ser mayores a cero.';if(form.horas_dia<.01||form.horas_dia>24)return 'Las horas diarias deben estar entre 0.01 y 24.';if(!Number.isInteger(form.tolerancia_tardanza_minutos)||form.tolerancia_tardanza_minutos<0||form.tolerancia_tardanza_minutos>1440)return 'La tolerancia debe ser un entero entre 0 y 1440 minutos.';return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarRegimen(editing.value,{...form,codigo:form.codigo.trim().toUpperCase(),descripcion:form.descripcion.trim().toUpperCase()});modal.value=false;success.value=`Régimen ${editing.value?'actualizado':'registrado'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:Regimen){const action=item.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} el régimen ${item.descripcion}?`))return;try{const r=await cambiarEstadoRegimen(item.id);item.estado=r.estado;success.value=r.message??`Régimen ${item.estado?'activado':'desactivado'} correctamente.`}catch(v){error.value=message(v)}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Regímenes laborales</nav><header class="hero"><div class="mark">RL</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Regímenes laborales</h1><p>Jornada, tareaje, tardanzas y beneficios aplicables al personal.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nuevo régimen</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><label>Buscar por código o descripción<input v-model.trim="criterio" placeholder="Ej. 728 o CAS"></label><button>Buscar</button><button type="button" class="soft" @click="criterio='';load(1)">Limpiar</button></form><section class="table-card"><header><div><small>CONFIGURACIÓN LABORAL</small><h2>Regímenes registrados</h2></div></header><div v-if="loading" class="empty">Consultando regímenes…</div><div v-else-if="!rows.length" class="empty">No se encontraron regímenes.</div><div v-else class="scroll"><table><thead><tr><th>Código</th><th>Descripción</th><th>Horas mes/día</th><th>Tareaje</th><th>Tolerancia</th><th>Descuento</th><th>Beneficios</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.codigo}}</b></td><td>{{item.descripcion}}</td><td>{{Number(item.horas_ordinarias_mes).toFixed(2)}} / {{Number(item.horas_dia).toFixed(2)}}</td><td>{{baseTareajeLabels[item.base_tareaje_default]}}</td><td>{{item.tolerancia_tardanza_minutos}} min</td><td>{{descuentoLabels[item.modo_descuento_tardanza]}}</td><td class="benefits"><span :class="item.afecto_gratificacion?'yes':'no'">G</span><span :class="item.afecto_cts?'yes':'no'">CTS</span><span :class="item.afecto_vacaciones?'yes':'no'">V</span></td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">RL</div><div><small>CONFIGURACIÓN LABORAL</small><h2>{{editing?'Editar':'Registrar'}} régimen</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="10" @input="form.codigo=form.codigo.toUpperCase()"></label><label class="span2">Descripción *<input v-model="form.descripcion" maxlength="150" @input="form.descripcion=form.descripcion.toUpperCase()"></label><h3>Configuración de jornada</h3><label>Horas ordinarias al mes *<input v-model.number="form.horas_ordinarias_mes" type="number" min="0.01" step="0.01"></label><label>Horas del día *<input v-model.number="form.horas_dia" type="number" min="0.01" max="24" step="0.01"></label><label>Base de tareaje *<select v-model="form.base_tareaje_default"><option v-for="(label,value) in baseTareajeLabels" :key="value" :value="value">{{label}}</option></select></label><label>Tolerancia tardanza (min) *<input v-model.number="form.tolerancia_tardanza_minutos" type="number" min="0" max="1440" step="1"></label><label>Modo descuento *<select v-model="form.modo_descuento_tardanza"><option v-for="(label,value) in descuentoLabels" :key="value" :value="value">{{label}}</option></select></label><h3>Beneficios</h3><div class="checks"><label><input v-model="form.afecto_gratificacion" type="checkbox"> Gratificación</label><label><input v-model="form.afecto_cts" type="checkbox"> CTS</label><label><input v-model="form.afecto_vacaciones" type="checkbox"> Vacaciones</label></div></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#fff0f5;font-size:.52rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:13px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{margin-right:auto;width:min(440px,100%);font-size:.52rem}.filters input,.dialog input,.dialog select{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:1050px;border-collapse:collapse;font-size:.52rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}.active,.inactive,.yes,.no{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.42rem}.active,.yes{color:#287154;background:#e6f7ee}.inactive,.no{color:#9d4046;background:#fdebed}.benefits{display:flex;gap:3px}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(850px,100%);max-height:92vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:8px;font-size:.5rem}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.span2{grid-column:span 2}.grid h3,.checks{grid-column:1/-1}.grid h3{margin:14px 0 0;padding-bottom:5px;border-bottom:1px solid #e8ecee;font-size:.6rem}.checks{display:flex;gap:18px;padding:10px;border-radius:7px;background:#f6f8f9}.checks label{display:flex;align-items:center;gap:5px;margin:0}.checks input{width:auto;margin:0}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:760px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%}.grid{grid-template-columns:1fr}.span2{grid-column:auto}.grid h3,.checks{grid-column:auto}.checks{flex-direction:column}.actions{min-width:140px}}
</style>
